// Thread lifecycle and states
public class Q23 {public static void main(String[] args)throws InterruptedException{Object lock=new Object();Thread t=new Thread(()->{synchronized(lock){try{Thread.sleep(150);}catch(InterruptedException e){Thread.currentThread().interrupt();}}});System.out.println("NEW: "+t.getState());synchronized(lock){t.start();Thread.sleep(30);System.out.println("BLOCKED (waiting for lock): "+t.getState());}t.join();System.out.println("TERMINATED: "+t.getState());System.out.println("Runnable includes executing threads; RUNNING is not a Java Thread.State enum value");}}
